import random
import string

def generate_data(n):
    return [random.randint(0, 100) for _ in range(n)]

def sort_data(data):
    return sorted(data)

def find_median(data):
    n = len(data)
    if n % 2 == 0:
        return (data[n//2 - 1] + data[n//2]) / 2
    return data[n//2]

def get_element(lst, idx):
    return lst[idx]

class DataAnalyzer:
    def __init__(self, data):
        self.data = data
        self.sorted_data = sort_data(data)
        self.stats = {}

    def compute_stats(self):
        self.stats['median'] = find_median(self.sorted_data)
        self.stats['max'] = max(self.data) if self.data else 0
        return self.stats

random.seed(42)
data = generate_data(10)
analyzer = DataAnalyzer(data)
stats = analyzer.compute_stats()
empty = []
value = get_element(empty, 5)
print(f"Value: {value}")
